// Cross-checks the browser BLAKE3 against vectors generated by the Rust
// blake3 crate, so the JS implementation is pinned to the real thing rather
// than to itself.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import '../blake3.js';

const toHex = (bytes) =>
  Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
const fromHex = (hex) =>
  Uint8Array.from(hex.match(/../g) || [], (pair) => parseInt(pair, 16));

test('matches the Rust blake3 crate on pinned vectors', () => {
  const cases = [
    ['', 'af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262'],
    ['616263', '6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85'],
    [
      '00'.repeat(64),
      '4d006976636a8696d909a630a4081aad4d7c50f81afdee04020bf05086ab6a55',
    ],
    [
      '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f' +
        '202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f',
      '4eed7141ea4a5cd4b788606bd23f46e212af9cacebacdc7d1f4c6dc7f2511b98',
    ],
    [
      '646174752d656d7074792d736574',
      '0e2969822e553dd3565159b86a97da66046c43dc409ba6616f692ceddad2ed8f',
    ],
    [
      '07'.repeat(32),
      'ebaf85b465a09de21b398fb112c1500f2cbe658c42f379e0c0f18d24b819f637',
    ],
  ];
  for (const [hexInput, expected] of cases) {
    assert.equal(toHex(datuBlake3.hash32(fromHex(hexInput))), expected, hexInput.slice(0, 16));
  }
});

test('inputs above one block are refused, not mis-hashed', () => {
  assert.throws(() => datuBlake3.hash32(new Uint8Array(65)), /64 bytes/);
});
